import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as l,o as t,af as i}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Hello Agents（DataWhale）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/agent/hello-agents-datwhale.md","filePath":"zh/tech/agent/hello-agents-datwhale.md","lastUpdated":1780925615000}'),o={name:"zh/tech/agent/hello-agents-datwhale.md"};function n(r,a,h,s,g,d){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="hello-agents-datawhale" tabindex="-1">Hello Agents（DataWhale） <a class="header-anchor" href="#hello-agents-datawhale" aria-label="Permalink to &quot;Hello Agents（DataWhale）&quot;">​</a></h1><blockquote><p>来源：<a href="https://datawhalechina.github.io/hello-agents/#/" target="_blank" rel="noreferrer">DataWhale Hello Agents</a>，一个开源的 Agent 学习教程</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>Hello Agents 是 DataWhale 出品的 Agent 学习教程，旨在帮助学习者从零开始理解 Agent 的概念、架构和实践方法。</p><p>教程涵盖：</p><ul><li>Agent 基础概念</li><li>主流 Agent 框架</li><li>工具使用和设计</li><li>实际项目实战</li></ul><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><p>教程设计了完整的学习路径，从基础概念到进阶实践：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基础概念 → 框架学习 → 工具设计 → 项目实战</span></span></code></pre></div><h2 id="核心内容模块" tabindex="-1">核心内容模块 <a class="header-anchor" href="#核心内容模块" aria-label="Permalink to &quot;核心内容模块&quot;">​</a></h2><h3 id="_1-agent-基础" tabindex="-1">1. Agent 基础 <a class="header-anchor" href="#_1-agent-基础" aria-label="Permalink to &quot;1. Agent 基础&quot;">​</a></h3><p>理解什么是 Agent：一种利用大语言模型进行推理、规划和执行动作的系统。</p><p>关键组件：</p><ul><li><strong>Planning</strong>：任务分解和规划</li><li><strong>Memory</strong>：记忆管理</li><li><strong>Tools</strong>：工具调用能力</li><li><strong>Action</strong>：执行具体动作</li></ul><h3 id="_2-主流框架" tabindex="-1">2. 主流框架 <a class="header-anchor" href="#_2-主流框架" aria-label="Permalink to &quot;2. 主流框架&quot;">​</a></h3><p>教程涵盖了当前主流的 Agent 开发框架，包括：</p><ul><li>LangChain</li><li>AutoGPT</li><li>LlamaIndex</li><li>其他开源框架</li></ul><h3 id="_3-工具设计" tabindex="-1">3. 工具设计 <a class="header-anchor" href="#_3-工具设计" aria-label="Permalink to &quot;3. 工具设计&quot;">​</a></h3><p>工具是 Agent 与外部世界交互的桥梁。好的工具设计需要：</p><ul><li>清晰的工具描述</li><li>合理的参数设计</li><li>明确的返回值格式</li></ul><h3 id="_4-memory-管理" tabindex="-1">4. Memory 管理 <a class="header-anchor" href="#_4-memory-管理" aria-label="Permalink to &quot;4. Memory 管理&quot;">​</a></h3><p>Agent 需要记忆来：</p><ul><li>保持对话上下文</li><li>存储中间结果</li><li>跨 session 持久化</li></ul><p>常见的 Memory 策略：</p><ul><li>短窗口记忆（直接放入上下文）</li><li>长期记忆（向量数据库或文件存储）</li><li>混合策略（分层记忆管理）</li></ul><h3 id="_5-项目实战" tabindex="-1">5. 项目实战 <a class="header-anchor" href="#_5-项目实战" aria-label="Permalink to &quot;5. 项目实战&quot;">​</a></h3><p>通过实际项目学习 Agent 开发，理论与实践结合。</p><hr><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ol><li><strong>先理解概念</strong>：Agent 的核心是 LLM + 工具 + 规划能力</li><li><strong>多动手实践</strong>：看源码、改代码、做实验</li><li><strong>关注工具设计</strong>：工具设计质量直接影响 Agent 效果</li><li><strong>理解 Memory 重要性</strong>：上下文管理是 Agent 工程的关键难点</li></ol><hr><h2 id="相关资源" tabindex="-1">相关资源 <a class="header-anchor" href="#相关资源" aria-label="Permalink to &quot;相关资源&quot;">​</a></h2><ul><li>官方文档：<a href="https://datawhalechina.github.io/hello-agents/#/" target="_blank" rel="noreferrer">https://datawhalechina.github.io/hello-agents/#/</a></li><li>GitHub：DataWhale 仓库</li></ul><blockquote><p>注：本笔记基于 Hello Agents 教程大纲整理，具体内容请参考<a href="https://datawhalechina.github.io/hello-agents/#/" target="_blank" rel="noreferrer">官方教程</a>。</p></blockquote>',34)])])}const _=e